    if (!accessToken) return;
    setErr("");
    setLoading(true);
    apiFetch("/api/products/mine", { headers: { Authorization: `Bearer ${accessToken}` } })
      .then((d) => setRows(d.products || []))
      .catch((ex) => setErr(ex.message || "Failed to load"))
